// Skills.jsx
import { useEffect, useRef, useState } from 'react';
import './styles.css';
import { LOGOS } from './logos'; // logos are embedded in logos.js, no image files needed

const logo = (file) => LOGOS[file];

const ROW_ONE = [
  { name: 'React',        icon: logo('react') },
  { name: 'HTML5',        icon: logo('html5') },
  { name: 'CSS3',         icon: logo('css3') },
  { name: 'JavaScript',   icon: logo('javascript') },
  { name: 'Tailwind CSS', icon: logo('tailwindcss') },
  { name: 'Figma',        icon: logo('figma') },
  { name: 'Git',          icon: logo('git') },
  { name: 'GitHub',       icon: logo('github') },
  { name: 'PHP',          icon: logo('php') },
  { name: 'Linux',        icon: logo('linux') },
  { name: 'Arduino',      icon: logo('arduino') },
];

const ROW_TWO = [
  { name: 'Node.js',    icon: logo('nodejs') },
  { name: 'Express.js', icon: logo('express') },
  { name: 'MongoDB',    icon: logo('mongodb') },
  { name: 'Python',     icon: logo('python') },
  { name: 'Java',       icon: logo('java') },
  { name: 'Cisco',      icon: logo('cisco') },
  { name: 'Postman',    icon: logo('postman') },
  { name: 'VS Code',    icon: logo('vscode') },
  { name: 'Supabase',   icon: logo('supabase') },
  { name: 'PostgreSQL', icon: logo('postgresql') },
  { name: 'WAMP Server', icon: logo('wamp') },
  { name: 'XAMPP Server', icon: logo('xampp') },
];

function SkillTile({ skill, lit, onToggle, hidden }) {
  return (
    <button
      type="button"
      className={`skill-tile ${lit ? 'is-lit' : ''}`}
      onClick={() => onToggle(skill.name)}
      aria-pressed={lit}
      aria-label={skill.name}
      tabIndex={hidden ? -1 : 0}
    >
      <span className="skill-logo-wrap">
        <img
          className="skill-logo"
          src={skill.icon}
          alt=""
          draggable="false"
          onError={(e) => {
            e.currentTarget.style.display = 'none';
            e.currentTarget.parentElement.dataset.fallback = skill.name[0];
          }}
        />
      </span>
      <span className="skill-tile-name">{skill.name}</span>
    </button>
  );
}

/* A row that glides left → right on its own. The movement is a GPU
   transform with its own sub-pixel position, so it never stutters.
   You can still drag, swipe or wheel it; hovering, touching or
   focusing eases it to a stop, and it eases back up to speed after. */
function MarqueeRow({ items, speed, lit, onToggle }) {
  const rowRef = useRef(null);
  const trackRef = useRef(null);
  const motion = useRef({ x: 0, vel: 0, gw: 0 });
  const hover = useRef(false);
  const focus = useRef(false);
  const touch = useRef(false);
  const touchTimer = useRef(null);
  const drag = useRef({ down: false, dragging: false, moved: false, startX: 0, startPos: 0, lastX: 0, lastT: 0, v: 0 });

  useEffect(() => {
    const track = trackRef.current;
    const m = motion.current;
    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    // One group's width = the distance after which the loop repeats
    const measure = () => { m.gw = track.firstElementChild.offsetWidth; };
    const wrap = () => {
      if (!m.gw) return;
      const p = -m.x;                       // keep x inside (-gw, 0]
      m.x = -(((p % m.gw) + m.gw) % m.gw);
    };

    measure();
    m.x = -m.gw / 2;

    let raf;
    let last;
    const tick = (now) => {
      if (last === undefined) last = now;
      const dt = Math.min(now - last, 50) / 1000;
      last = now;

      if (!drag.current.dragging) {
        const held = hover.current || focus.current || touch.current || reduce;
        const target = held ? 0 : speed;                 // + = moving right
        m.vel += (target - m.vel) * (1 - Math.exp(-dt * 3.5)); // ease in / out
        m.x += m.vel * dt;
      }
      wrap();
      track.style.transform = `translate3d(${m.x}px, 0, 0)`;
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);

    window.addEventListener('resize', measure);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener('resize', measure);
      clearTimeout(touchTimer.current);
    };
  }, [speed]);

  const holdTouch = (ms) => {
    clearTimeout(touchTimer.current);
    touch.current = true;
    touchTimer.current = setTimeout(() => (touch.current = false), ms);
  };

  const onPointerEnter = (e) => { if (e.pointerType === 'mouse') hover.current = true; };
  const onPointerLeave = (e) => { if (e.pointerType === 'mouse') hover.current = false; };

  const onPointerDown = (e) => {
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const d = drag.current;
    d.down = true;
    d.dragging = false;
    d.moved = false;
    d.startX = d.lastX = e.clientX;
    d.startPos = motion.current.x;
    d.lastT = performance.now();
    d.v = 0;
    if (e.pointerType !== 'mouse') {
      clearTimeout(touchTimer.current);
      touch.current = true;
    }
  };

  const onPointerMove = (e) => {
    const d = drag.current;
    if (!d.down) return;
    const dx = e.clientX - d.startX;
    if (!d.dragging && Math.abs(dx) > 5) {
      d.dragging = true;
      d.moved = true;
      rowRef.current.setPointerCapture(e.pointerId); // only once it's a real drag, so taps still click
      rowRef.current.classList.add('is-dragging');
    }
    if (d.dragging) {
      motion.current.x = d.startPos + dx;
      const now = performance.now();
      const dt = (now - d.lastT) / 1000;
      if (dt > 0) d.v = d.v * 0.6 + ((e.clientX - d.lastX) / dt) * 0.4;
      d.lastX = e.clientX;
      d.lastT = now;
    }
  };

  const endDrag = (e) => {
    const d = drag.current;
    if (!d.down) return;
    d.down = false;
    if (d.dragging) {
      d.dragging = false;
      motion.current.vel = Math.max(-1600, Math.min(1600, d.v)); // flick, then ease back to normal
      rowRef.current.classList.remove('is-dragging');
    }
    if (e.pointerType !== 'mouse') holdTouch(1800);
  };

  // A drag shouldn't count as a click on the logo underneath
  const onClickCapture = (e) => {
    if (drag.current.moved) {
      e.stopPropagation();
      e.preventDefault();
      drag.current.moved = false;
    }
  };

  // Horizontal trackpad / shift+wheel moves the row
  const onWheel = (e) => {
    const delta = e.deltaX || (e.shiftKey ? e.deltaY : 0);
    if (!delta) return;
    motion.current.x -= delta;
    holdTouch(1200);
  };

  const group = (hidden) => (
    <ul className="marquee-group" aria-hidden={hidden || undefined}>
      {[...items, ...items].map((skill, i) => (
        <li key={`${skill.name}-${i}`}>
          <SkillTile skill={skill} lit={lit.has(skill.name)} onToggle={onToggle} hidden={hidden} />
        </li>
      ))}
    </ul>
  );

  return (
    <div
      ref={rowRef}
      className="marquee-row"
      onPointerEnter={onPointerEnter}
      onPointerLeave={onPointerLeave}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={endDrag}
      onPointerCancel={endDrag}
      onClickCapture={onClickCapture}
      onWheel={onWheel}
      onFocus={() => (focus.current = true)}
      onBlur={() => (focus.current = false)}
      onScroll={(e) => { e.currentTarget.scrollLeft = 0; }} // keyboard focus must not scroll the row itself
    >
      <div ref={trackRef} className="marquee-track">
        {group(false)}
        {group(true)}
      </div>
    </div>
  );
}

export default function Skills() {
  const [lit, setLit] = useState(() => new Set());

  const toggle = (name) =>
    setLit((prev) => {
      const next = new Set(prev);
      next.has(name) ? next.delete(name) : next.add(name);
      return next;
    });

  return (
    <section className="skills-section">
      <div className="section-tag">Skills & Tools</div>
      <h2 className="section-title">
        Technologies <span className="highlight">I use</span>
      </h2>
      <p className="section-sub">
        From full‑stack development to design and networking — tools I use daily to build robust digital solutions.
      </p>

      <div className="skills-marquee">
        <MarqueeRow items={ROW_ONE} speed={42} lit={lit} onToggle={toggle} />
        <MarqueeRow items={ROW_TWO} speed={32} lit={lit} onToggle={toggle} />
      </div>

      <p className="skills-hint">Drag or swipe to scroll. Hover to pause and see a logo's colors. Click to keep it lit.</p>
    </section>
  );
}
